import math
from qiskit import QuantumCircuit


def _phase_on(qc, qubits, value):
    """Apply a -1 phase to the basis state `value` of the listed qubits (little-endian)."""
    zeros = [q for i, q in enumerate(qubits) if not (value >> i) & 1]
    for q in zeros:
        qc.x(q)
    qc.mcp(math.pi, qubits[:-1], qubits[-1])
    for q in zeros:
        qc.x(q)


def _coin3_gate():
    """Coin I - 2|s><s| on slots {0,1,2}, s uniform; identity on slot 3 (eq_2 coin)."""
    theta = 2.0 * math.asin(math.sqrt(1.0 / 3.0))
    w = QuantumCircuit(2)
    w.ry(theta, 1)
    w.ch(1, 0, ctrl_state=0)
    sub = QuantumCircuit(2)
    sub.compose(w.inverse(), inplace=True)
    sub.x([0, 1])
    sub.cz(0, 1)
    sub.x([0, 1])
    sub.compose(w, inplace=True)
    return sub.to_gate(label="coin3")


def _swap_states(qc, a, b):
    """Transposition of 5-qubit basis states a and b (index = slot + 4*vertex)."""
    diff = [i for i in range(5) if ((a ^ b) >> i) & 1]
    k = diff[0]
    others = diff[1:]
    for j in others:
        qc.cx(k, j)
    ap = a
    if (a >> k) & 1:
        for j in others:
            ap ^= (1 << j)
    controls = [i for i in range(5) if i != k]
    cs = 0
    for idx, c in enumerate(controls):
        cs |= ((ap >> c) & 1) << idx
    qc.mcx(controls, k, ctrl_state=cs)
    for j in reversed(others):
        qc.cx(k, j)


def _parse(instance):
    if not isinstance(instance, dict):
        raise ValueError("instance must be a dict")
    if "x" not in instance or "steps" not in instance:
        raise ValueError("instance needs keys x and steps")
    x = instance["x"]
    if not isinstance(x, (list, tuple)) or len(x) != 4:
        raise ValueError("x must be a list of 4 bits")
    bits = []
    for v in x:
        if isinstance(v, bool):
            v = int(v)
        if not isinstance(v, int) or v not in (0, 1):
            raise ValueError("x entries must be 0 or 1")
        bits.append(v)
    t = instance["steps"]
    if isinstance(t, bool) or not isinstance(t, int) or t < 1 or t > 64:
        raise ValueError("steps must be an integer in 1..64")
    return bits, t


def _step(qc, x, coin3):
    """One walk step U_x = S_x C_x (eq_2)."""
    # coin: degree-1 vertices (tail and present leaves) get -1 on slot 0
    _phase_on(qc, [0, 1, 2, 3, 4], 0)
    for i in range(4):
        if x[i] == 1:
            _phase_on(qc, [0, 1, 2, 3, 4], 4 * (4 + i))
    # degree-3 coins at root, a, b
    for v in (1, 2, 3):
        qc.append(coin3.control(3, ctrl_state=v), [2, 3, 4, 0, 1])
    # flip-flop shift: swap |u, slot toward v> <-> |v, slot toward u>
    edges = [((0, 0), (1, 0), None), ((1, 1), (2, 0), None), ((1, 2), (3, 0), None),
             ((2, 1), (4, 0), 0), ((2, 2), (5, 0), 1), ((3, 1), (6, 0), 2), ((3, 2), (7, 0), 3)]
    for (u, su), (v, sv), leaf in edges:
        if leaf is not None and x[leaf] == 0:
            continue  # absent edge: self-loop, state fixed
        _swap_states(qc, su + 4 * u, sv + 4 * v)


def build_circuit(instance):
    x, t = _parse(instance)
    qc = QuantumCircuit(5, name="nand_walk")
    coin3 = _coin3_gate()
    for _ in range(t):
        _step(qc, x, coin3)
    return qc

import math
from qiskit import QuantumCircuit, QuantumRegister


def _mcx(qc, ctrls, bits, t):
    cs = sum(b << i for i, b in enumerate(bits))
    qc.mcx(list(ctrls), t, ctrl_state=cs)


def _phase(qc, qs, bits):
    # phase -1 on the basis pattern bits over qubits qs
    t = qs[-1]
    if bits[-1] == 0:
        qc.x(t)
    qc.h(t)
    _mcx(qc, qs[:-1], bits[:-1], t)
    qc.h(t)
    if bits[-1] == 0:
        qc.x(t)


def _coin(qc, v, slots):
    # eq_2 coin C_v on used slots of vertex v, controlled on vertex == v
    vq = [2, 3, 4]
    vb = [(v >> i) & 1 for i in range(3)]
    d = len(slots)
    if d == 1:
        _phase(qc, [0, 1] + vq, [0, 0] + vb)
    elif d == 2:
        if slots[1] == 1:
            _mcx(qc, [1] + vq, [0] + vb, 0)
        else:
            _mcx(qc, [0] + vq, [0] + vb, 1)
    else:
        th = 2.0 * math.asin(1.0 / math.sqrt(3.0))
        qc.ry(th, 1)
        qc.ch(1, 0, ctrl_state=0)
        for sb in ([1, 0], [0, 1], [1, 1]):
            _phase(qc, [0, 1] + vq, sb + vb)
        qc.ch(1, 0, ctrl_state=0)
        qc.ry(-th, 1)
        _phase(qc, [0, 1] + vq, [1, 1] + vb)


def _swap(qc, a, b):
    # exchange basis states |a> and |b> of the 5 qubits
    dbits = [i for i in range(5) if ((a ^ b) >> i) & 1]
    p = dbits[0]
    others = dbits[1:]
    for q in others:
        qc.cx(p, q)
    ap = a
    if (a >> p) & 1:
        for q in others:
            ap ^= 1 << q
    ctl = [i for i in range(5) if i != p]
    _mcx(qc, ctl, [(ap >> i) & 1 for i in ctl], p)
    for q in others:
        qc.cx(p, q)


def build_circuit(instance):
    if not isinstance(instance, dict):
        raise ValueError('instance must be a dict')
    x = instance.get('x')
    if not isinstance(x, (list, tuple)) or len(x) != 4:
        raise ValueError('x must be a list of 4 bits')
    for b in x:
        if isinstance(b, bool) or not isinstance(b, int) or b not in (0, 1):
            raise ValueError('x entries must be 0 or 1')
    steps = instance.get('steps', 4)
    if isinstance(steps, bool) or not isinstance(steps, int) or steps < 1 or steps > 32:
        raise ValueError('steps must be an integer in 1..32')
    slot = QuantumRegister(2, 'slot')
    vert = QuantumRegister(3, 'vertex')
    qc = QuantumCircuit(slot, vert)
    # vertices: 0 tail, 1 root, 2 and 3 internal, 4..7 leaves (leaf 4+i present iff x[i]=1)
    s2 = [0] + ([1] if x[0] else []) + ([2] if x[1] else [])
    s3 = [0] + ([1] if x[2] else []) + ([2] if x[3] else [])
    coins = [(0, [0]), (1, [0, 1, 2]), (2, s2), (3, s3)]
    edges = [((0, 0), (1, 0)), ((1, 1), (2, 0)), ((1, 2), (3, 0))]
    for i, (par, sl) in enumerate([(2, 1), (2, 2), (3, 1), (3, 2)]):
        if x[i]:
            coins.append((4 + i, [0]))
            edges.append(((par, sl), (4 + i, 0)))
    for _ in range(steps):
        for v, sl in coins:
            _coin(qc, v, sl)
        for (u, su), (w, sw) in edges:
            _swap(qc, 4 * u + su, 4 * w + sw)
    return qc
